    { name = "Melee crit", text = "0.7% + Agility ÷ the Agility per 1% crit at your level", expr = "0.7 + agi / agiPerCrit", game = "crit", unit = "%", note = "The game's number also counts crit from your gear, your weapon skill and buffs.", digits = 2, estimate = true, numbers = { { "0.7%", "your class's crit chance before Agility", "the original game's rule" }, { "the Agility per 1% crit at your level", "1% per 20 Agility at level 60; below 60, 20 × your level ÷ 60 (levels under 10 count as 10)", "the original game's rule at level 60; below it the planner's estimate, not yet checked on Forever. Forever's own character sheet showed about 5.4 Agility per 1% crit on a level 11 Warrior where this rule gives 3.7, so it's too generous at low levels; Forever has no function an addon can ask for the game's own rule" } } },
    { name = "Spell crit", text = "1% per 54 Intellect at level 60; below 60, 1% per 54 × your level ÷ 60 (levels under 10 count as 10)", expr = "0 + int / (54 * max(10, level) / 60)", game = "spellCrit", unit = "%", note = "The game's number also counts spell crit from your gear and buffs.", digits = 2, estimate = true, numbers = { { "1% per 54 Intellect at level 60", "how much Intellect buys 1% spell crit at the level cap", "the original game's rule" }, { "× your level ÷ 60", "lower levels need less Intellect for 1%", "the planner's estimate, not yet checked on Forever. A guild Priest and Druid at levels 6 and 7 showed 4.7 to 4.9% spell crit, where this gives 3.4 to 4.5%" }, { "levels under 10 count as 10", "keeps the first levels from getting a huge spell crit chance", "the planner's estimate, not yet checked on Forever" } } },
