    { name = "Physical damage your armor stops", text = "your armor ÷ (your armor + 400 + 85 × the attacker's level), at most 75%. Here: an attacker of your level.", expr = "min(75, armor / (armor + 400 + 85 * level) * 100)", game = "armorStops", unit = "%", digits = 1, numbers = { { "400 + 85 × the attacker's level", "the armor that stops exactly half: with that much armor you take 50% less", "the original game's rule, checked on Forever: the game's own number for your armor (GetArmorEffectiveness) agrees (the tick)" }, { "at most 75%", "armor never stops more than this", "the original game's rule" }, { "an attacker of your level", "who hits you on this line; Effective health below uses a raid boss", "the planner's own choice" } } },
    { name = "Effective health", text = "how much damage you can take before you die, what the planner calls survival: health ÷ (the share of a raid boss's hits that gets through your armor × the share that doesn't miss and you don't dodge, parry or block). The boss is 3 levels above you; its 5% misses, your dodge, parry and block (with a shield) count up to 60% together.", expr = "health / ((1 - min(0.75, armor / (armor + 400 + 85 * (level + 3)))) * (1 - min(0.6, 0.05 + (dodge + parry + block) / 100)))", digits = 0, numbers = { { "3 levels above you", "a raid boss: the planner measures every tank against one", "the planner's own choice" }, { "5%", "an attack's base chance to miss you", "the original game's rule" }, { "up to 60%", "misses + dodge + parry + block are counted up to 60%, so stacking them can't make the number run away", "the planner's own choice" } } },
